function normalizeState(){
  const base=fresh();
  state=deepMerge(base,state||{});
  window.state=state;
  const validScreens=['setup','menu','hub','career','specialty','shift','post','learning','outpatient','emergency','settings','recovery'];
  if(!validScreens.includes(state.screen)) state.screen='hub';
  state.locale=normalizeLocale(state.locale);
  state.accessibility=normalizeAccessibility(state.accessibility);
  state.audio=normalizeAudioPreferences(state.audio||{enabled:state.sound!==false});state.sound=state.audio.enabled;
  state.presentation=normalizePresentationPreferences(state.presentation||{});
  state.beta=deepMerge(base.beta,state.beta||{});
  state.beta.localTelemetry=Boolean(state.beta.localTelemetry);
  state.beta.checklist=state.beta.checklist&&typeof state.beta.checklist==='object'?state.beta.checklist:{};
  state.beta.devices=state.beta.devices&&typeof state.beta.devices==='object'?state.beta.devices:{};
  state.beta.reports=Array.isArray(state.beta.reports)?state.beta.reports.slice(-10):[];
  state.actions=deepMerge({questions:[],exams:[],procedures:[],hypotheses:[],conduct:[]},state.actions||{});
  state.assessment=deepMerge({interview:[],physicalExam:[],redFlags:[],communication:0,lastFinding:null},state.assessment||{});
  state.therapeutics=createTherapeuticsState(activeCase?.()?.id||null,state.therapeutics||null);
  state.emergency=deepMerge({scenarioId:null,session:null,completed:[],xpClaimed:[]},state.emergency||{});
  state.outpatient=deepMerge({programId:null,session:null,completed:[],xpClaimed:[]},state.outpatient||{});
  state.difficulty=['beginner','student','professional','challenge'].includes(state.difficulty)?state.difficulty:'student';
  state.branching=deepMerge({session:null,completed:[],xpClaimed:[]},state.branching||{});
  state.career=createCareerState(careerRegistry,state.career||null);
  state.prontuario=deepMerge({history:[],exams:[],procedures:[],hypotheses:[],conduct:[],notes:[]},state.prontuario||{});
  state.missions=deepMerge({claimed:[]},state.missions||{});
  state.player=deepMerge(base.player,state.player||{});
  state.currentCase=Number.isFinite(Number(state.currentCase))?Number(state.currentCase):0;
  state.simulation=deepMerge({minutes:720,criticality:0,physiology:null},state.simulation||{});
  state.meta=deepMerge(base.meta,state.meta||{});state.meta.locale=state.locale;
  state.ui=deepMerge({shiftTab:'summary',recordTab:'overview',resultsOpen:false,closureReview:false,compactProfile:true,academyView:'catalog',academyModuleId:null,academyLessonIndex:0,academyQuizFeedback:null,emergencyTab:'summary',outpatientTab:'summary',careerTab:'overview',betaTab:'status'},state.ui||{});
  state.academy=deepMerge(base.academy,state.academy||{});
  state.pwa=deepMerge({installDismissed:false,lastInstallResult:null},state.pwa||{});
  applyDocumentLocale(state.locale);
  applyAccessibilityPreferences(state.accessibility);
}

