function showRecoveryScreen(err){
  try{
    const msg=(err&&(err.message||String(err)))||'Erro desconhecido';
    state.meta=state.meta||{};state.meta.recoveryCount=(state.meta.recoveryCount||0)+1;
    diagnostics.error('runtime','Modo segurança ativado.',{message:msg,screen:state.screen,recoveryCount:state.meta.recoveryCount});
    try{stateStore.save(state,{label:'runtime-error',forceBackup:true});}catch{}
    app.innerHTML=`<main class="screen fade recovery-screen" style="--bg:url('${bg(8)}')"><section class="setup panel pop recovery-card"><p class="safety-kicker">RECUPERAÇÃO SEGURA</p><h1>Não foi possível continuar</h1><p>Seu progresso foi preservado. Tente voltar ao lobby ou abra a área de recuperação para escolher um backup.</p><div class="recovery-actions"><button class="btn primary" onclick="safeRecoverHub()">Voltar ao lobby</button><button class="btn" onclick="openRecoveryCenter()">Gerenciar progresso</button><button class="btn" onclick="safeExportSave()">Exportar progresso</button><button class="btn danger" onclick="safeFreshStart()">Recomeçar perfil</button></div></section><div class="build">${BUILD.label}</div></main>`;
    applyCurrentLocale();
  }catch{document.body.innerHTML='<h1>Medical Simulator</h1><p>Modo segurança.</p><button onclick="location.reload()">Recarregar</button>';}
}
