function applyGameContent(content,status={mode:'fallback',warnings:[]}){
  exams=[...(content.gameplay.exams||[])];
  procedures=[...(content.gameplay.procedures||[])];
  hypotheses=[...(content.gameplay.hypotheses||[])];
  conducts=[...(content.gameplay.conducts||[])];
  directedQuestions=[...(content.gameplay.directedQuestions||[])];
  patients=[...(content.queue.patients||[])];
  governanceRegistry=content.governance||null;
  academyContent=content.academy||getFallbackContent().academy;
  physiologyRegistry=content.physiology||getFallbackContent().physiology;
  assessmentRegistry=content.assessment||getFallbackContent().assessment;
  therapeuticsRegistry=content.therapeutics||getFallbackContent().therapeutics;
  emergencyRegistry=content.emergency||getFallbackContent().emergency;
  outpatientRegistry=content.outpatient||getFallbackContent().outpatient;
  branchingRegistry=content.branching||getFallbackContent().branching;
  careerRegistry=content.career||getFallbackContent().career;
  const registeredCases=[...(content.cases||[])];
  governanceSummary=buildGovernanceSummary(governanceRegistry,registeredCases);
  cases=registeredCases.filter(item=>isCasePlayable(governanceRegistry,item.id));
  if(!cases.length)throw new Error('A governança médica bloqueou todos os casos clínicos.');
  specs=(content.specialties.specialties||[]).map(item=>[item.id,item.name,item.description,item.icon,item.declaredCaseCount,bg(item.background),item.unlockLevel]);
  missionBank=[...(content.missions.missions||[])];
  examResultBank=content.responses.examResults||{};
  questionResultBank=content.responses.questionResults||{};
  procedureResultBank=content.responses.procedureResults||{};
  window.VALE_CONTENT_STATUS={...status,caseCount:cases.length,registeredCaseCount:registeredCases.length,contentVersion:BUILD.version,governance:governanceSummary,academyModules:academyContent?.modules?.length||0,physiologyProfiles:physiologyRegistry?.profiles?.length||0,assessmentProfiles:assessmentRegistry?.cases?.length||0,therapeuticsProfiles:therapeuticsRegistry?.patientProfiles?.length||0,emergencyScenarios:emergencyRegistry?.scenarios?.length||0,outpatientPrograms:outpatientRegistry?.programs?.length||0,branchingProfiles:branchingRegistry?.cases?.length||0,difficulties:branchingRegistry?.difficulties?.length||0,careerStages:careerRegistry?.stages?.length||0,careerDepartments:careerRegistry?.departments?.length||0};
  window.VALE_GOVERNANCE_STATUS=governanceSummary;
  diagnostics.info('content','Pacote clínico ativado.',{mode:status.mode,source:status.source||'unknown',caseCount:cases.length,registeredCaseCount:registeredCases.length,releaseReady:governanceSummary.ready,governanceBlocked:governanceSummary.blockedCount,warnings:status.warnings?.length||0});
  state.meta.contentMode=status.mode||'fallback';
}
