function xpNeed(l){return 500+(l-1)*420}function syncProgress(){let p=state.player,lvl=1,spent=p.xp;while(spent>=xpNeed(lvl)&&lvl<20){spent-=xpNeed(lvl);lvl++}p.level=lvl;p.title=p.xp>=4200?'Especialista Vale':p.xp>=2600?'Médico Clínico':p.xp>=1400?'Residente R2':p.xp>=600?'Residente R1':'Interno';state.unlocks=state.unlocks||{specialties:['clinica-medica']};[['urgencia',2],['cardiologia',3],['pediatria',4]].forEach(x=>{if(p.level>=x[1]&&!state.unlocks.specialties.includes(x[0]))state.unlocks.specialties.push(x[0])});p.rank=Math.max(1,1248-Math.floor(p.xp/8)-(p.highScoreCases||0)*12);return{spent,next:xpNeed(lvl),pct:Math.min(100,Math.round(spent/xpNeed(lvl)*100))}}
function rep(sc){return sc>=90?'Excelente':sc>=78?'Boa':sc>=62?'Instável':'Em observação'}
function casesForSelectedSpecialty(){let filtered=cases.filter(c=>c.specialty===state.selectedSpec);if(!filtered.length){state.selectedSpec='clinica-medica';filtered=cases.filter(c=>c.specialty===state.selectedSpec);}return filtered.length?filtered:cases}
function activeCase(){const pool=casesForSelectedSpecialty();return pool[state.currentCase%pool.length]}
function activeBranchProfile(){return branchingProfileForCase(branchingRegistry,activeCase()?.id);}
function activeDifficulty(){return difficultyDefinition(branchingRegistry,state.difficulty);}
function ensureBranchingSession(){const c=activeCase();state.branching=state.branching||{session:null,completed:[],xpClaimed:[]};state.branching.session=createBranchingSession(c?.id,state.difficulty,branchingRegistry,state.branching.session);return state.branching.session;}
function registerBranch(type,value){const session=ensureBranchingSession();const result=registerBranchEvidence(session,branchingRegistry,{type,value,at:minToClock()});if(result.unlocked.length){state.timeline.push({t:minToClock(),text:`Nova pista clínica liberada (${result.unlocked.length})`});toast(result.unlocked.length===1?'Nova pista clínica liberada':`${result.unlocked.length} pistas clínicas liberadas`,'ok');}return result;}
function branchClues(){return visibleBranchClues(ensureBranchingSession(),branchingRegistry);}
function localizedBranch(value){return localizeBranching(value,state.locale);}
function activeHypotheses(){const profile=activeBranchProfile();return profile?.differentials?.length?profile.differentials:hypotheses;}
function difficultyBadge(){const d=activeDifficulty();return `<span class="difficulty-badge difficulty-${esc(d?.id||'student')}">${esc(localizedBranch(d?.label)||'Estudante')}</span>`;}

let physiologyTimer=null;
function activePhysiologyProfile(caseId=activeCase()?.id){return profileForCase(physiologyRegistry,caseId);}
function ensurePhysiologySession(){
  const c=activeCase(),profile=activePhysiologyProfile(c?.id);if(!c||!profile)throw new Error('Perfil fisiológico indisponível para o caso ativo.');
  const previous=state.simulation?.physiology;
  const isNew=!previous||previous.caseId!==c.id;
  state.simulation.physiology=createPhysiologySession(c,profile,previous,Date.now());
  if(isNew){const legacyElapsed=Math.max(0,720-Number(state.simulation?.minutes||720));if(legacyElapsed)advancePhysiology(state.simulation.physiology,profile,Math.min(legacyElapsed,30),{reason:'migration',label:'Tempo migrado da versão anterior'});}
  syncPhysiologyState();return state.simulation.physiology;
}
function syncPhysiologyState(){
  const session=state.simulation?.physiology;if(!session)return;
  const v=formatPhysiologyVitals(session);state.simulation.minutes=Math.max(0,720-v.elapsedMinutes);
  state.simulation.criticality=session.status==='unstable'?18:session.status==='attention'?9:session.status==='improving'?0:Math.max(0,Math.round((100-v.reserve)/12));
}
function currentPhysiology(){const session=ensurePhysiologySession();return{session,profile:activePhysiologyProfile(session.caseId),vitals:formatPhysiologyVitals(session)};}
function handlePhysiologyEvents(events=[]){
  for(const event of events){state.timeline.push({t:minToClock(),text:event.message});diagnostics[event.level==='critical'?'warn':'info']?.('physiology',event.message,{caseId:activeCase()?.id,minute:state.simulation.physiology?.elapsedMinutes});if(event.level==='critical'||event.level==='warning')toast(event.message,'warn');}
}
function advanceClinicalTime(minutes,{reason='tick',label='Evolução clínica',saveNow=false}={}){
  const {session,profile}=currentPhysiology();const before=session.status;const result=advancePhysiology(session,profile,minutes,{reason,label});syncPhysiologyState();handlePhysiologyEvents(result.events);
  if(saveNow||Math.floor(session.elapsedMinutes/5)>Math.floor((session.lastAutosaveMinute||0)/5)){session.lastAutosaveMinute=session.elapsedMinutes;save({label:'physiology-'+reason});}
  processReadyDiagnostics({notify:reason!=='continuous'});
  return{...result,statusChanged:before!==session.status};
}
function applyActionToPhysiology(type,value){
  const {session,profile}=currentPhysiology();const cost=Number(physiologyRegistry?.actionTimeCost?.[type]??2);const before=session.status;
  const result=applyPhysiologyAction(session,profile,type,value,cost);syncPhysiologyState();handlePhysiologyEvents(result.events);processReadyDiagnostics({notify:true});return{...result,cost,statusChanged:before!==session.status};
}
function updatePhysiologyDom(){
  if(state.screen!=='shift'||!state.simulation?.physiology)return;const v=formatPhysiologyVitals(state.simulation.physiology);const map={pa:v.pa,fc:v.fc,fr:v.fr,temp:v.temp,spo2:v.spo2,status:statusLabel(v.status,state.locale),symptom:v.symptom,reserve:v.reserve,clock:minToClock(),elapsed:v.elapsedMinutes};
  for(const [key,value] of Object.entries(map))for(const el of document.querySelectorAll?.(`[data-physiology="${key}"]`)||[])el.textContent=String(value);
  const root=document.querySelector?.('.patient-command');if(root)root.dataset.physiologyStatus=v.status;
}
function stopPhysiologyClock(){if(physiologyTimer){clearInterval(physiologyTimer);physiologyTimer=null;}}
function syncPhysiologyClock(){
  stopPhysiologyClock();if(state.screen!=='shift'||orientationBlocked||document.hidden)return;const session=ensurePhysiologySession();session.lastRealTickAt=Date.now();
  const seconds=Math.max(4,Number(physiologyRegistry?.tick?.realSecondsPerClinicalMinute||12));const maxCatchup=Math.max(1,Number(physiologyRegistry?.tick?.maxCatchupMinutes||5));
  physiologyTimer=setInterval(()=>{if(state.screen!=='shift'||document.hidden||orientationBlocked){session.lastRealTickAt=Date.now();return;}const now=Date.now();const delta=Math.min(maxCatchup,Math.floor((now-session.lastRealTickAt)/(seconds*1000)));if(delta<1)return;session.lastRealTickAt+=delta*seconds*1000;const result=advanceClinicalTime(delta,{reason:'continuous',label:'Evolução contínua'});updatePhysiologyDom();if(result.statusChanged)render();},1000);physiologyTimer.unref?.();
}
function currentCaseGovernance(caseId=activeCase()?.id){return getCaseGovernance(governanceRegistry,caseId);}
function governanceTone(status){return status==='clinically-approved'?'approved':status==='clinical-review'?'review':status==='reference-mapped'?'mapped':'blocked';}
function governanceStatusBadge(caseId=activeCase()?.id){const record=currentCaseGovernance(caseId);if(!record)return '<span class="governance-chip blocked">Governança ausente</span>';return `<span class="governance-chip ${governanceTone(record.status)}" title="${esc((record.reviewNotes||[]).join(' '))}">⚕ ${esc(governanceStatusLabel(record.status))}</span>`;}
function governanceDisclaimerText(){const localized=governanceRegistry?.policy?.disclaimer?.[state.locale];return localized||governanceRegistry?.policy?.disclaimer?.['pt-BR']||'Conteúdo educacional. Não substitui atendimento profissional.';}
function governanceSettingsCard(){
  const sourceById=new Map((governanceRegistry?.sources||[]).map(source=>[source.id,source]));
  const rows=(governanceSummary.items||[]).map(item=>{const record=currentCaseGovernance(item.caseId);const clinicalCase=cases.find(c=>c.id===item.caseId)||{patient:item.caseId,diagnosis:item.caseId};const sources=(record?.sourceIds||[]).map(id=>sourceById.get(id)).filter(Boolean);return `<details class="governance-case"><summary><span><b>${esc(clinicalCase.patient)}</b><small>${esc(clinicalCase.diagnosis)}</small></span>${governanceStatusBadge(item.caseId)}</summary><div class="governance-case-body"><p><b>Região de referência:</b> ${esc(record?.region||'Não informada')}</p><p><b>Publicável:</b> ${record?.publishable?'Sim':'Não — uso interno de desenvolvimento'}</p>${(record?.reviewNotes||[]).map(note=>`<p class="governance-note">⚠ ${esc(note)}</p>`).join('')}<p><b>Bloqueios:</b> ${item.blockers.length?item.blockers.map(esc).join(' • '):'Nenhum'}</p><div class="governance-sources">${sources.map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(source.organization)}</b><small>${esc(source.title)} • ${esc(source.year)} • ${esc(source.region)}</small></a>`).join('')}</div></div></details>`;}).join('');
  return `<section class="card governance-card" aria-labelledby="governance-title"><div class="governance-head"><div><small>GOVERNANÇA MÉDICA</small><h2 id="governance-title">Fontes, revisão e bloqueio de publicação</h2><p>${esc(governanceDisclaimerText())}</p></div><span class="release-gate ${governanceSummary.ready?'ready':'blocked'}">${governanceSummary.ready?'LIBERADO':'PUBLICAÇÃO BLOQUEADA'}</span></div><div class="governance-kpis"><div><small>Casos aprovados</small><b>${governanceSummary.approvedCount}/${governanceSummary.total}</b></div><div><small>Fontes oficiais</small><b>${governanceSummary.activeSourceCount||0}</b></div><div><small>Canal</small><b>${esc(governanceSummary.channel||'development')}</b></div><div><small>Schema</small><b>${BUILD.contentSchema}</b></div></div><p class="governance-gate-copy">A build de desenvolvimento permanece jogável, mas o script de release encerra com erro enquanto qualquer caso ativo não tiver responsável clínico, revisão médica independente, revisão trilíngue e auditoria de segurança.</p><button class="btn" onclick="exportGovernanceReport()">Exportar relatório de governança</button><div class="governance-case-list">${rows}</div></section>`;
}
function activeTherapeuticProfile(){return therapeuticProfileForCase(therapeuticsRegistry,activeCase()?.id);}
function ensureTherapeuticsSession(){const c=activeCase();state.therapeutics=createTherapeuticsState(c?.id,state.therapeutics);return state.therapeutics;}
function localizedValue(value){return localizeTherapeutic(value,state.locale);}
function orderClock(minute){const total=8*60+Math.max(0,Math.round(Number(minute||0)));return `${String(Math.floor(total/60)%24).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function processReadyDiagnostics({notify=true}={}){const session=ensureTherapeuticsSession(),elapsed=Number(state.simulation?.physiology?.elapsedMinutes||0);const ready=processExamOrders(session,therapeuticsRegistry,activeCase().id,elapsed,examResultBank);if(!ready.length)return ready;ensureClinicalState();for(const order of ready){if(state.prontuario.exams.some(x=>x.orderId===order.id))continue;const response={kind:'exams',title:'Resultado liberado',text:order.result,detail:`${order.value} • solicitado ${orderClock(order.requestedAt)} • liberado ${orderClock(order.releasedAt)}`,time:minToClock()};state.prontuario.exams.push({time:minToClock(),label:order.value,result:order.result,detail:response.detail,caseId:activeCase().id,orderId:order.id,status:'ready'});state.timeline.push({t:minToClock(),text:`Resultado liberado: ${order.value}`});state.encounter=response;}if(notify){state.popup={kind:'Exame',title:ready.length===1?ready[0].value:`${ready.length} resultados liberados`,text:ready.length===1?ready[0].result:'Novos resultados estão disponíveis na central clínica.',detail:'Revise o resultado no prontuário antes de decidir a conduta.',time:minToClock()};toast(ready.length===1?'Resultado de exame liberado':`${ready.length} resultados liberados`,'ok');}save({label:'diagnostic-results'});return ready;}
function examOrderFor(value){return ensureTherapeuticsSession().examOrders.find(x=>x.value===value&&x.status!=='cancelled')||null;}
function toggleExamOrder(value){const y=Math.max(0,window.scrollY||0),session=ensureTherapeuticsSession(),existing=examOrderFor(value);if(existing){if(existing.status!=='processing'){toast('Resultado já liberado; o registro não pode ser apagado.','warn');return;}const cancelled=cancelExamOrder(session,value);if(cancelled.ok){state.actions.exams=state.actions.exams.filter(x=>x!==value);state.encounter={kind:'Pedido cancelado',title:value,text:'O pedido foi cancelado antes da liberação.',detail:'O tempo já consumido não é recuperado.',time:minToClock()};state.timeline.push({t:minToClock(),text:`Pedido cancelado: ${value}`});toast('Pedido cancelado','tap');save({label:'exam-cancel'});render();requestAnimationFrame(()=>window.scrollTo?.({top:y,left:0,behavior:'auto'}));}return;}
 if(!state.actions.exams.includes(value))state.actions.exams.push(value);registerBranch('exam',value);const physiology=applyActionToPhysiology('exams',value);const requested=requestExamOrder(session,therapeuticsRegistry,activeCase().id,value,Number(state.simulation?.physiology?.elapsedMinutes||0));const def=requested.definition||examDefinition(therapeuticsRegistry,value);state.encounter={kind:'Pedido de exame',title:value,text:`Pedido registrado. Liberação estimada em ${def?.turnaroundMinutes||'?'} minutos clínicos.`,detail:`Amostra/preparo: ${localizedValue(def?.specimen)}. Tempo comprimido para fins educacionais.${physiology.effect?' Resposta fisiológica específica registrada.':''}`,time:minToClock()};ensureClinicalState();state.prontuario.notes.push({time:minToClock(),label:`Pedido: ${value}`,result:state.encounter.text,detail:state.encounter.detail,caseId:activeCase().id,orderId:requested.order?.id,status:'processing'});state.timeline.push({t:minToClock(),text:`Exame solicitado: ${value}`});toast('Exame solicitado','ok');save({label:'exam-request'});render();requestAnimationFrame(()=>window.scrollTo?.({top:y,left:0,behavior:'auto'}));setTimeout(focusClinicalPanel,80);}
function safetyCheckLabel(key){const labels={identity:['Identidade e paciente','Identity and patient','Identidad y paciente'],allergies:['Alergias e reações','Allergies and reactions','Alergias y reacciones'],currentMedications:['Medicamentos atuais','Current medicines','Medicamentos actuales'],renalHepatic:['Função renal/hepática','Renal/hepatic function','Función renal/hepática'],pregnancy:['Gestação quando aplicável','Pregnancy when applicable','Embarazo cuando corresponda'],indicationRoute:['Indicação, dose e via','Indication, dose, and route','Indicación, dosis y vía']};const i=state.locale==='en'?1:state.locale==='es'?2:0;return labels[key]?.[i]||key;}
function toggleMedicationSafetyCheck(key){const session=ensureTherapeuticsSession();if(!(key in session.reconciliation.checks))return;session.reconciliation.checks[key]=!session.reconciliation.checks[key];session.reconciliation.confirmed=false;session.reconciliation.confirmedAt=null;save({label:'medication-check'});render();}
function confirmMedicationReconciliation(){const session=ensureTherapeuticsSession(),required=therapeuticsRegistry.requiredSafetyChecks||[];const missing=required.filter(key=>session.reconciliation.checks[key]!==true);if(missing.length){toast(`Complete ${missing.length} verificação(ões) de segurança.`,'warn');return;}session.reconciliation.confirmed=true;session.reconciliation.confirmedAt=minToClock();state.timeline.push({t:minToClock(),text:'Reconciliação medicamentosa confirmada'});save({label:'medication-reconciliation'});toast('Reconciliação confirmada','ok');render();}
function toggleConductOrder(value){const y=Math.max(0,window.scrollY||0),session=ensureTherapeuticsSession();if(state.actions.conduct.includes(value)){state.actions.conduct=state.actions.conduct.filter(x=>x!==value);state.encounter={kind:'Ação removida',title:'Plano atualizado',text:`${value} foi removido do plano ativo.`,detail:'Uma administração já registrada não é desfeita.',time:minToClock()};save({label:'conduct-remove'});render();requestAnimationFrame(()=>window.scrollTo?.({top:y,left:0,behavior:'auto'}));return;}
 const assessment=assessIntervention(therapeuticsRegistry,activeCase().id,value,session.reconciliation);if(assessment.blocked){state.encounter={kind:'Barreira de segurança',title:'Ordem bloqueada',text:assessment.reasons.join(' '),detail:'Conclua a reconciliação e revise contraindicações antes de prosseguir.',time:minToClock()};toast('Ordem bloqueada pela segurança medicamentosa','warn');save({label:'conduct-blocked'});render();return;}
 state.actions.conduct.push(value);registerBranch('conduct',value);const registered=registerIntervention(session,therapeuticsRegistry,activeCase().id,value,Number(state.simulation?.physiology?.elapsedMinutes||0));const physiology=applyActionToPhysiology('conduct',value);const def=registered.definition;const order=def?.order&&typeof def.order==='object'?`${def.order.dose} • ${def.order.route} • ${def.order.frequency} • ${def.order.duration}`:localizedValue(def?.order);state.encounter={kind:def?.kind==='medication'?'Ordem medicamentosa':'Conduta registrada',title:localizedValue(def?.label)||value,text:registered.recommended?'Intervenção compatível com a indicação do cenário.':'Intervenção sem indicação prevista: incidente de segurança simulado registrado.',detail:`${order||''}${localizedValue(def?.warnings)?' • '+localizedValue(def.warnings):''}${physiology.effect?' • resposta fisiológica específica registrada':''}`,time:minToClock()};recordClinical('conduct',value,state.encounter);state.timeline.push({t:minToClock(),text:`Conduta: ${value}`});toast(registered.recommended?'Conduta registrada':'Incidente de segurança simulado','warn');save({label:'conduct-order'});render();requestAnimationFrame(()=>window.scrollTo?.({top:y,left:0,behavior:'auto'}));setTimeout(focusClinicalPanel,80);}

function selected(type,val){return state.actions[type].includes(val)}
function addTime(kind){const cost=Number(physiologyRegistry?.actionTimeCost?.[kind]??2);advanceClinicalTime(cost,{reason:kind,label:'Tempo clínico: '+kind,saveNow:true});return cost}
function toggleAction(type,val){if(type==='exams'){toggleExamOrder(val);return;}if(type==='conduct'){toggleConductOrder(val);return;}let arr=state.actions[type];if(type==='hypotheses'&&!arr.includes(val)&&arr.length>=hypothesisLimit(branchingRegistry,state.difficulty)){toast(`Limite de ${hypothesisLimit(branchingRegistry,state.difficulty)} hipótese(s) neste nível.`,'warn');return;}if(arr.includes(val)){state.actions[type]=arr.filter(x=>x!==val);state.encounter={kind:'Ação removida',title:'Registro atualizado',text:val+' foi removido do raciocínio ativo.',detail:'A remoção não desfaz efeitos fisiológicos já ocorridos.',time:minToClock()};toast('Ação removida','tap')}else{arr.push(val);registerBranch(type,val);const physiology=applyActionToPhysiology(type,val);state.encounter=clinicalResponse(type,val);state.encounter.detail+=(physiology.effect?' Resposta fisiológica específica registrada.':' Sem efeito fisiológico direto previsto neste perfil.');recordClinical(type,val,state.encounter);state.timeline.push({t:minToClock(),text:state.encounter.title+': '+val});toast('Resposta clínica registrada','ok')}save({label:'clinical-action'});render();setTimeout(focusClinicalPanel,80)}
function minToClock(){const elapsed=Math.max(0,Math.round(Number(state.simulation?.physiology?.elapsedMinutes??(720-Number(state.simulation?.minutes||720)))));const total=8*60+elapsed;const h=Math.floor(total/60)%24,mi=total%60;return `${String(h).padStart(2,'0')}:${String(mi).padStart(2,'0')}`}
function esc(v){return String(v||'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]||m))}
function defaultEncounter(){const c=activeCase();return {kind:'Queixa inicial',title:'Relato espontâneo do paciente',text:'Doutor(a), estou sentindo '+c.complaint+'.',detail:'Use anamnese, exame físico e exames complementares para transformar a queixa em raciocínio clínico.',time:minToClock()}}
function clinicalResponse(type,val){const c=activeCase();let text='',title='',detail='';if(type==='questions'){title='Resposta da anamnese';text=(questionResultBank[c.id]&&questionResultBank[c.id][val])||'Paciente responde, mas a informação não muda muito a hipótese principal neste momento.';detail='Pergunta feita: '+val}if(type==='exams'){title='Resultado de exame';text=(examResultBank[c.id]&&examResultBank[c.id][val])||val+': resultado sem alterações relevantes para a queixa atual. Pode representar exame de baixa utilidade neste caso.';detail='Exame solicitado: '+val}if(type==='procedures'){title='Achado do procedimento';text=procedureResultBank[val]||'Procedimento realizado sem intercorrências. Achado inespecífico.';detail='Procedimento: '+val}if(type==='hypotheses'){title='Hipótese diagnóstica registrada';text=val===c.diagnosis?'Hipótese forte: combina bem com queixa, sinais e achados obtidos até agora.':'Hipótese registrada, mas ainda exige evidências melhores para sustentar essa linha diagnóstica.';detail='Hipótese: '+val}if(type==='conduct'){title='Conduta registrada';text=c.idealConduct.includes(val)?'Conduta coerente com o caso. Ela contribui positivamente para segurança, seguimento e desfecho do paciente.':'Conduta anotada, porém pode não ser a prioridade ideal para este quadro. Revise a lógica clínica antes de finalizar.';detail='Conduta: '+val}return {kind:type,title,text,detail,time:minToClock()}}
function typeWriter(){const el=document.querySelector('#typewriter');if(!el)return;const txt=el.dataset.text||'';if(prefersReducedMotion(state.accessibility)){el.textContent=txt;return;}el.textContent='';let i=0;const step=()=>{el.textContent=txt.slice(0,i++);if(i<=txt.length)setTimeout(step,12)};step()}
function closePopup(){state.popup=null;save();render()}window.closePopup=closePopup;

function ensureClinicalState(){
  state.prontuario=state.prontuario||{history:[],exams:[],procedures:[],hypotheses:[],conduct:[],notes:[]};
  state.vitalTrend=state.vitalTrend||[];
}
function recordClinical(type,val,response){
  ensureClinicalState();
  const item={time:minToClock(),label:val,result:response.text,detail:response.detail||'',caseId:activeCase().id};
  const map={questions:'history',exams:'exams',procedures:'procedures',hypotheses:'hypotheses',conduct:'conduct'};
  const bucket=map[type]||'notes';
  state.prontuario[bucket].push(item);
}
function updateVitals(){syncPhysiologyState();}
function clinicalRecords(){
  ensureClinicalState();
  const groups=[
    ['history','Anamnese','💬'],['exams','Exames','🧪'],['procedures','Exame físico','⚕'],
    ['hypotheses','Hipóteses','🧠'],['conduct','Condutas','📋'],['notes','Notas','✎']
  ];
  return groups.flatMap(([bucket,label,icon])=>(state.prontuario[bucket]||[]).map((item,index)=>({...item,bucket,group:label,icon,index})))
    .sort((a,b)=>String(a.time).localeCompare(String(b.time)));
}
function clockFromElapsed(minutes=0){const total=8*60+Math.max(0,Math.round(Number(minutes)||0));return `${String(Math.floor(total/60)%24).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function latestVitals(){const {vitals}=currentPhysiology();return{time:minToClock(),pa:vitals.pa,fc:vitals.fc,fr:vitals.fr,temp:vitals.temp,spo2:vitals.spo2,status:statusLabel(vitals.status,state.locale),statusCode:vitals.status,symptom:vitals.symptom,reserve:vitals.reserve,outcome:vitals.outcome,elapsedMinutes:vitals.elapsedMinutes};}
function clinicalProgress(){
  const checks=[
    ['questions','Anamnese',state.actions.questions.length>0],
    ['exams','Exames',state.actions.exams.length>0],
    ['procedures','Exame físico',state.actions.procedures.length>0],
    ['diagnosis','Diagnóstico',state.actions.hypotheses.length>0],
    ['conduct','Conduta',state.actions.conduct.length>0]
  ];
  const complete=checks.filter(x=>x[2]).length;
  return {checks,complete,pct:Math.round(complete/checks.length*100),actions:Object.values(state.actions).reduce((sum,list)=>sum+list.length,0)};
}
function workflowBar(){
  const progress=clinicalProgress();
  const map={questions:'questions',exams:'exams',procedures:'procedures',diagnosis:'diagnosis',conduct:'diagnosis'};
  return `<section class="clinical-workflow panel"><div class="workflow-copy"><small>FLUXO DO ATENDIMENTO</small><b>${progress.complete}/5 etapas documentadas</b><div class="workflow-meter"><i style="width:${progress.pct}%"></i></div></div><div class="workflow-steps">${progress.checks.map(([id,label,done],index)=>`<button class="workflow-step ${done?'done':''}" aria-label="Etapa ${index+1}: ${label}${done?', concluída':''}" onclick="setShiftTab('${map[id]}')"><span>${done?'✓':index+1}</span><small>${label}</small></button>`).join('')}</div><button class="results-center-btn" onclick="toggleResultsCenter()">▤ <span>Resultados</span><b>${state.prontuario.exams.length+state.prontuario.procedures.length}</b></button></section>`;
}
function patientCommandHeader(){
  const c=activeCase(),v=latestVitals(),statusCode=v.statusCode||'stable';
  return `<section class="patient-command panel" data-physiology-status="${statusCode}"><div class="patient-command-id"><span class="status-beacon ${statusCode==='unstable'?'critical':statusCode==='attention'?'attention':'stable'}"></span><div><small>PACIENTE EM ATENDIMENTO</small><h2>${esc(c.patient)}</h2><p>${c.age} anos • ${esc(c.sex)} • ${esc(c.profession)} • ${esc(specs.find(x=>x[0]===state.selectedSpec)?.[1]||'Clínica Médica')}</p><div class="patient-governance">${governanceStatusBadge(c.id)}${difficultyBadge()}<small>${esc(governanceDisclaimerText())}</small></div></div></div><div class="command-vitals physiology-vitals"><div><small>PA</small><b data-physiology="pa">${esc(v.pa)}</b></div><div><small>FC</small><b data-physiology="fc">${v.fc}</b></div><div><small>FR</small><b data-physiology="fr">${v.fr}</b></div><div><small>SpO₂</small><b><span data-physiology="spo2">${v.spo2}</span>%</b></div><div><small>Estado</small><b data-physiology="status">${esc(v.status)}</b></div></div><div class="command-clock"><small>TEMPO CLÍNICO CONTÍNUO</small><b data-physiology="clock">${minToClock()}</b><em>Sintomas <span data-physiology="symptom">${v.symptom}</span>/100 • Reserva <span data-physiology="reserve">${v.reserve}</span>%</em><button class="reassess-btn" onclick="reassessPatient()">↻ Reavaliar</button></div></section>`;
}
function recordTabs(){
  const tabs=[['overview','Visão geral'],['history','Anamnese'],['results','Resultados'],['plan','Hipóteses/Plano'],['vitals','Sinais vitais'],['timeline','Linha do tempo']];
  return `<nav class="record-tabs" role="tablist" aria-label="Seções do prontuário">${tabs.map(([id,label])=>`<button role="tab" aria-selected="${state.ui.recordTab===id}" class="${state.ui.recordTab===id?'active':''}" onclick="setRecordTab('${id}')">${label}</button>`).join('')}</nav>`;
}
function recordItems(items,empty){
  return items.length?`<div class="record-feed">${items.slice().reverse().map(x=>`<article class="record-entry"><div><span>${x.icon||'•'}</span><b>${esc(x.label)}</b><time>${esc(x.time)}</time></div><p>${esc(x.result)}</p>${x.detail?`<small>${esc(x.detail)}</small>`:''}</article>`).join('')}</div>`:`<div class="record-empty"><b>Nenhum registro</b><p>${empty}</p></div>`;
}
function recordOverview(){
  const c=activeCase(),all=clinicalRecords();
  const activeHyp=state.actions.hypotheses;
  const activeConduct=state.actions.conduct;
  return `<div class="record-overview"><div class="record-summary premium"><small>QUEIXA PRINCIPAL</small><h3>${esc(c.complaint)}</h3><p>${esc((state.encounter||defaultEncounter()).text)}</p></div><div class="record-kpis"><div><small>Perguntas</small><b>${state.actions.questions.length}</b></div><div><small>Exames</small><b>${state.actions.exams.length}</b></div><div><small>Exame físico</small><b>${state.actions.procedures.length}</b></div><div><small>Registros</small><b>${all.length}</b></div></div><section class="active-clinical-plan"><div><small>HIPÓTESES ATIVAS</small>${activeHyp.length?`<div class="clinical-chips">${activeHyp.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'<p>Nenhuma hipótese selecionada.</p>'}</div><div><small>CONDUTAS ATIVAS</small>${activeConduct.length?`<div class="clinical-chips conduct">${activeConduct.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'<p>Nenhuma conduta selecionada.</p>'}</div></section><h4>Últimos registros</h4>${recordItems(all.slice(-4),'As ações clínicas aparecerão aqui em ordem cronológica.')}</div>`;
}
function prontuarioPanel(){
  ensureClinicalState();
  const c=activeCase();
  const tab=state.ui.recordTab||'overview';
  const records=clinicalRecords();
  const by=bucket=>records.filter(x=>x.bucket===bucket);
  let body='';
  if(tab==='overview')body=recordOverview();
  if(tab==='history')body=recordItems(by('history'),'Faça perguntas dirigidas ou registre uma observação clínica.');
  if(tab==='results')body=recordItems([...by('exams'),...by('procedures')].sort((a,b)=>String(a.time).localeCompare(String(b.time))),'Exames e procedimentos aparecerão nesta central.');
  if(tab==='plan')body=recordItems([...by('hypotheses'),...by('conduct')].sort((a,b)=>String(a.time).localeCompare(String(b.time))),'Registre hipóteses e condutas antes do encerramento.');
  if(tab==='vitals')body=vitalChart();
  if(tab==='timeline')body=recordItems(records,'Nenhuma ação clínica registrada.');
  return `<div class="record-grid premium-record"><div class="record-head"><div><small>PRONTUÁRIO ELETRÔNICO</small><h3>${esc(c.patient)}</h3><p>${c.age} anos • ${esc(c.sex)} • Caso ${esc(c.id)}</p></div><button class="record-result-shortcut" onclick="toggleResultsCenter()">Abrir central de resultados</button></div>${recordTabs()}<div class="record-tab-body">${body}</div></div>`;
}
function vitalChart(){
  const session=ensurePhysiologySession();const data=(session.trend||[]).slice(-10);
  if(!data.length)return `<div class="record-empty vital-empty"><b>Sem tendência registrada</b><p>Os sinais vitais evolutivos serão registrados conforme o tempo e as ações clínicas.</p></div>`;
  const maxFc=Math.max(...data.map(x=>x.heartRate),100);
  return `<div class="vital-chart premium"><div class="vital-chart-legend"><span>Frequência cardíaca</span><span>SpO₂, sintomas e reserva</span></div>${data.map(x=>`<div class="vital-row"><span>${clockFromElapsed(x.minute)}</span><i style="width:${Math.round((x.heartRate/maxFc)*100)}%"></i><b>FC ${x.heartRate}</b><em>SpO₂ ${x.spo2}% • Sintomas ${x.symptomSeverity}/100 • ${esc(statusLabel(x.status,state.locale))}</em></div>`).join('')}</div>`;
}
function resetEncounterData(){stopPhysiologyClock();state.actions={questions:[],exams:[],procedures:[],hypotheses:[],conduct:[]};state.assessment={interview:[],physicalExam:[],redFlags:[],communication:0,lastFinding:null};state.therapeutics=createTherapeuticsState(activeCase()?.id,null);state.branching=state.branching||{session:null,completed:[],xpClaimed:[]};state.branching.session=null;state.timeline=[];state.encounter=null;state.popup=null;state.prontuario={history:[],exams:[],procedures:[],hypotheses:[],conduct:[],notes:[]};state.vitalTrend=[];state.simulation={minutes:720,criticality:0,physiology:null};state.ui.resultsOpen=false;state.ui.closureReview=false;state.ui.recordTab='overview';state.ui.shiftTab='summary';}

function clinicalPanel(){const e=state.encounter||defaultEncounter();return '<div class="clinical-board '+(e.kind==='exams'?'exam-mode':'')+'"><div class="board-head"><small>'+esc(e.kind)+'</small><b>'+esc(e.title)+'</b><time>'+esc(e.time||minToClock())+'</time></div><p id="typewriter" data-text="'+esc(e.text)+'"></p><div class="board-detail">'+esc(e.detail||'')+'</div></div>'}
function resultsCenterHtml(){
  if(!state.ui.resultsOpen)return '';
  const items=clinicalRecords().filter(x=>['exams','procedures'].includes(x.bucket)).reverse();const pending=ensureTherapeuticsSession().examOrders.filter(x=>x.status==='processing');
  return `<div class="modal-back results-center-back"><section class="results-center pop" role="dialog" aria-modal="true" aria-labelledby="results-center-title" tabindex="-1"><header><div><small>CENTRAL CLÍNICA</small><h2 id="results-center-title">Resultados e exame físico</h2><p>Histórico preservado em ordem de liberação.</p></div><button class="modal-x" onclick="toggleResultsCenter()" aria-label="Fechar central de resultados">×</button></header>${pending.length?`<div class="pending-results"><h3>Em processamento</h3>${pending.map(x=>`<article><div class="result-icon">⏳</div><div><small>Previsto ${orderClock(x.readyAt)}</small><h3>${esc(x.value)}</h3><p>Aguardando processamento do cenário.</p></div></article>`).join('')}</div>`:''}${items.length?`<div class="results-list">${items.map(x=>`<article><div class="result-icon">${x.icon}</div><div><small>${esc(x.group)} • ${esc(x.time)}</small><h3>${esc(x.label)}</h3><p>${esc(x.result)}</p><em>${esc(x.detail||'Registro clínico confirmado.')}</em></div></article>`).join('')}</div>`:'<div class="record-empty"><b>Nenhum resultado disponível</b><p>Solicite exames ou realize o exame físico para alimentar esta central.</p></div>'}<footer><button class="btn" onclick="setRecordTab('results');toggleResultsCenter();setShiftTab('record')">Abrir no prontuário</button><button class="btn primary" onclick="toggleResultsCenter()">Voltar ao atendimento</button></footer></section></div>`;
}
function popupHtml(){if(!state.popup)return '';const p=state.popup;return '<div class="modal-back"><div class="result-modal pop" role="dialog" aria-modal="true" aria-labelledby="result-modal-title" tabindex="-1"><button class="modal-x" onclick="closePopup()" aria-label="Fechar resultado">×</button><small>'+esc(p.kind)+'</small><h2 id="result-modal-title">'+esc(p.title)+'</h2><p>'+esc(p.text)+'</p><em>'+esc(p.detail)+'</em><div class="modal-actions"><button class="btn" onclick="closePopup();toggleResultsCenter()">Ver histórico</button><button class="btn primary" onclick="closePopup()">Continuar</button></div></div></div>'}
function closureReviewHtml(){
  if(!state.ui.closureReview)return '';
  const c=activeCase(),progress=clinicalProgress(),branchSession=ensureBranchingSession(),clues=branchClues();
  const warnings=[];
  if(!state.actions.questions.length)warnings.push('Nenhuma pergunta dirigida registrada.');
  if(!state.actions.hypotheses.length)warnings.push('Nenhuma hipótese diagnóstica selecionada.');
  if(!state.actions.conduct.length)warnings.push('Nenhuma conduta selecionada.');
  const pendingOrders=ensureTherapeuticsSession().examOrders.filter(x=>x.status==='processing');if(pendingOrders.length)warnings.push(`${pendingOrders.length} exame(s) ainda em processamento.`);
  const medicationSelected=state.actions.conduct.some(x=>interventionDefinition(therapeuticsRegistry,x)?.kind==='medication');if(medicationSelected&&!ensureTherapeuticsSession().reconciliation.confirmed)warnings.push('Há ordem medicamentosa sem reconciliação confirmada.');
  return `<div class="modal-back"><section class="closure-review pop" role="dialog" aria-modal="true" aria-labelledby="closure-review-title" tabindex="-1"><header><small>REVISÃO DE ENCERRAMENTO</small><h2 id="closure-review-title">Confirmar conclusão da consulta?</h2><p>Revise o raciocínio ativo antes de registrar o desfecho.</p></header><div class="closure-grid"><div><small>PACIENTE</small><b>${esc(c.patient)}</b></div><div><small>ETAPAS</small><b>${progress.complete}/5</b></div><div><small>AÇÕES</small><b>${progress.actions}</b></div><div><small>TEMPO</small><b>${minToClock()}</b></div><div><small>EVOLUÇÃO</small><b>${esc(latestVitals().status)}</b></div><div><small>SINTOMAS</small><b>${latestVitals().symptom}/100</b></div><div><small>DIFICULDADE</small><b>${esc(localizedBranch(activeDifficulty()?.label))}</b></div><div><small>PISTAS</small><b>${clues.length}/${activeBranchProfile()?.clues?.length||0}</b></div></div><section><small>HIPÓTESES ATIVAS</small>${state.actions.hypotheses.length?`<div class="clinical-chips">${state.actions.hypotheses.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'<p>Nenhuma hipótese selecionada.</p>'}</section><section><small>CONDUTAS ATIVAS</small>${state.actions.conduct.length?`<div class="clinical-chips conduct">${state.actions.conduct.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'<p>Nenhuma conduta selecionada.</p>'}</section>${warnings.length?`<div class="closure-warnings"><b>Atenção antes de concluir</b>${warnings.map(x=>`<p>• ${esc(x)}</p>`).join('')}</div>`:'<div class="closure-ready">✓ Documentação mínima registrada.</div>'}<footer><button class="btn" onclick="cancelFinishReview()">Continuar atendimento</button><button class="btn primary" onclick="confirmFinishCase()">Confirmar e encerrar</button></footer></section></div>`;
}
function count(a,b){return a.filter(x=>b.includes(x)).length}
function rawClinicalScore(){const c=activeCase();let q=count(state.actions.questions,c.correctQuestions),e=count(state.actions.exams,c.correctExams),pr=count(state.actions.procedures,c.correctProcedures),co=count(state.actions.conduct,c.idealConduct);let diag=state.actions.hypotheses.includes(c.diagnosis)?25:0;const d=activeDifficulty();let excess=Math.max(0,state.actions.exams.length-c.correctExams.length)*6*Number(d?.excessPenaltyMultiplier||1);let missingConduct=Math.max(0,c.idealConduct.length-co)*4;const physiology=physiologyQuality(ensurePhysiologySession(),activePhysiologyProfile());return Math.max(15,Math.min(100,Math.round(q*6+e*7+pr*5+co*6+diag+physiology-excess-missingConduct-therapeuticsPenalty(ensureTherapeuticsSession()))));}
function calcScore(){return Math.max(15,Math.min(100,Math.round(rawClinicalScore()*difficultyMultiplier(branchingRegistry,state.difficulty,'scoreMultiplier'))));}
function currentBranchOutcome(score=calcScore()){const assessmentIds=[...(state.assessment?.interview||[]),...(state.assessment?.physicalExam||[])];return evaluateBranchOutcome(ensureBranchingSession(),branchingRegistry,{hypotheses:state.actions.hypotheses,conduct:state.actions.conduct,idealConduct:activeCase().idealConduct,score,physiologyStatus:latestVitals().statusCode,incidents:ensureTherapeuticsSession().incidents?.length||0,assessmentIds});}
function finishCaseCore(){state.ui.closureReview=false;state.ui.resultsOpen=false;stopPhysiologyClock();const c=activeCase(),phys=latestVitals(),sc=calcScore(),branch=currentBranchOutcome(sc),difficulty=state.difficulty;state.score=sc;state.completed.push({id:c.id,score:sc,at:BUILD.label,difficulty,branchOutcome:branch.id,branchQuality:branch.quality,clues:branchClues().length,differentials:[...state.actions.hypotheses],physiology:{status:phys.statusCode,outcome:phys.outcome,elapsedMinutes:phys.elapsedMinutes,symptom:phys.symptom,reserve:phys.reserve}});state.branching.completed.push({caseId:c.id,difficulty,outcome:branch.id,quality:branch.quality,score:sc,at:new Date().toISOString()});const xpMultiplier=difficultyMultiplier(branchingRegistry,difficulty,'xpMultiplier');state.player.xp+=Math.round(c.xp*(sc/100)*xpMultiplier);state.player.credits+=sc>=80?110:60;state.player.patients++;if(sc>=80)state.player.highScoreCases++;state.player.streak=sc>=75?state.player.streak+1:0;state.player.correct=Math.round((state.player.correct+sc)/2);state.player.reputation=rep(sc);recordCareerActivity(state.career,{type:'case',specialty:c.specialty,score:sc,id:c.id});state.currentCase=(state.currentCase+1)%casesForSelectedSpecialty().length;syncProgress();save({label:'case-complete',forceBackup:true});go('post')}
function missionProgress(m){return Math.min(m.goal,state.player[m.metric]||0)}function canClaim(m){return missionProgress(m)>=m.goal&&!state.missions.claimed.includes(m.id)}function claimMission(id){let m=missionBank.find(x=>x.id===id);if(!m||!canClaim(m))return toast('Missão ainda não concluída','warn');state.missions.claimed.push(id);state.player.xp+=m.rewardXp;state.player.credits+=m.rewardCredits;syncProgress();save();toast('Recompensa coletada!','level');render()}
function logo(){return `<div class="brand"><div class="pulse-line"></div><div class="logo"><span>Simulador de</span><b>Medicina</b></div><small>VALE EDITION • MODO SIMULADOR</small></div>`}
function profile(){let p=state.player,pr=syncProgress(),careerTitle=careerLocalized(currentCareerStage()?.title)||trTerm(p.title);return `<div class="profile panel" aria-label="Perfil do jogador"><img src="${av(p.avatar)}" alt="Avatar de ${esc(p.name)}"><div><strong>${esc(p.name)}</strong><em>${esc(careerTitle)} • ${tr('Nível')} ${p.level}</em><div class="xp" role="progressbar" aria-label="Progresso de experiência" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pr.pct}"><i style="width:${pr.pct}%"></i></div><small>${pr.spent} / ${pr.next} XP • Rep. ${esc(trTerm(p.reputation))}</small></div></div>`}
function top(section){const offline=!pwaStatus.online;const drawerEnabled=['hub','career','specialty','learning','settings','recovery'].includes(state.screen)||(state.screen==='outpatient'&&!state.outpatient?.session)||(state.screen==='emergency'&&!state.emergency?.session);const navigationButton=drawerEnabled?`<button class="hamb" onclick="toggleDrawer()" aria-label="Abrir menu principal" aria-expanded="${state.drawer}">☰</button>`:`<button class="hamb" onclick="go('hub')" aria-label="Voltar ao lobby">←</button>`;return `<header class="topbar">${logo()}<div class="top-actions"><label class="top-locale-wrap"><span class="sr-only">${tr('Preferência de idioma')}</span><select class="top-locale" aria-label="${tr('Preferência de idioma')}" onchange="setAppLocale(this.value)">${SUPPORTED_LOCALES.map(item=>`<option value="${item.id}" ${state.locale===item.id?'selected':''}>${item.short}</option>`).join('')}</select></label>${navigationButton}${pwaStatus.installAvailable&&!state.pwa.installDismissed?'<button class="install-btn" onclick="installGame()" aria-label="Instalar aplicativo">⬇ <span>Instalar</span></button>':''}<button class="fullscreen-btn" onclick="requestGameFullscreen()" aria-label="${pwaStatus.fullscreen?'Sair da tela cheia':'Ativar tela cheia'}" title="${pwaStatus.fullscreen?'Sair da tela cheia':'Tela cheia'}">${pwaStatus.fullscreen?'⤢':'⛶'}</button></div><h2 id="screen-title">${section}</h2><div class="runtime-pill ${offline?'offline':'online'}" role="status" aria-live="polite"><i aria-hidden="true"></i>${offline?'Offline':'Online'} • ${pwaStatus.displayMode==='browser'?'Navegador':'App'}</div>${profile()}</header>`}
function slug(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function shell(section,body,bgNum=8){return `<a class="skip-link" href="#main-content">Pular para o conteúdo principal</a><main id="main-content" tabindex="-1" class="screen fade screen-${slug(section)}" style="--bg:url('${bg(bgNum)}')" aria-labelledby="screen-title">${top(section)}${body}<div class="build" aria-label="Versão do aplicativo">${BUILD.label}</div></main>`}
function sidebar(active){let items=[['hub','🏠','Lobby','Visão geral'],['career','🎓','Carreira','Residência'],['learning','📖','Aprendizagem','Procedimentos'],['specialty','🩺','Plantão','Especialidades'],['outpatient','📆','Seguimento','Ambulatório'],['emergency','⚡','Emergência','ABCDE'],['settings','⚙️','Configurações','Preferências']];return `<aside class="side panel ${state.drawer?'open':''}" aria-label="Navegação principal">${items.map(x=>`<button onclick="go('${x[0]}')" class="nav ${active==x[0]?'active':''}" ${active==x[0]?'aria-current="page"':''}><span>${x[1]}</span><b>${x[2]}</b><small>${x[3]}</small></button>`).join('')}</aside><div class="shade ${state.drawer?'show':''}" onclick="toggleDrawer()"></div>`}
function setup(){app.innerHTML=`<a class="skip-link" href="#main-content">Pular para o conteúdo principal</a><main id="main-content" tabindex="-1" class="screen fade setup-screen" style="--bg:url('${bg(1)}')"><section class="setup-brand">${logo()}<p>Decisões clínicas, evolução profissional e aprendizagem em uma experiência imersiva.</p></section><section class="setup panel pop" aria-labelledby="setup-title"><header class="setup-heading"><small>CRIE SEU PERFIL</small><h1 id="setup-title">Comece sua jornada</h1></header><section class="setup-avatar-step"><h2>Escolha seu avatar</h2><div class="avatar-row" role="group" aria-label="Avatares disponíveis">${[1,2,3,4,5].map(i=>`<button class="avatar-choice ${state.player.avatar==i?'active':''}" onclick="pickAvatar(${i})" aria-label="Selecionar avatar ${i}" aria-pressed="${state.player.avatar==i}"><img src="${av(i)}" alt="Avatar ${i}"></button>`).join('')}</div></section><section class="setup-fields"><label for="name"><span>Nome do personagem</span><input class="input" id="name" value="${esc(state.player.name)}" autocomplete="name" maxlength="48"></label><label for="country"><span>País de origem</span><select class="input" id="country"><option>🇧🇷 Brasil</option></select></label><button class="btn primary setup-continue" onclick="startGame()">Continuar</button></section></section><div class="build">Versão ${BUILD.version}</div></main>`}
function menu(){app.innerHTML=`<a class="skip-link" href="#main-content">Pular para o conteúdo principal</a><main id="main-content" tabindex="-1" class="screen fade menu-screen" style="--bg:url('${bg(2)}')">${logo()}<section class="welcome slide"><h1>Bem-vindo,<br><span>${state.player.short}</span></h1><p>O conhecimento é a sua maior ferramenta. Cada decisão pode mudar uma vida.</p></section><section class="mode-grid"><article class="mode card" style="--cardbg:url('${bg(3)}')"><h2>Modo Carreira</h2><p>Construa sua trajetória, reputação e experiência clínica.</p><button class="btn primary" onclick="go('hub')">Entrar</button></article><article class="mode card" style="--cardbg:url('${bg(7)}')"><h2>Modo Simulador</h2><p>Resolva casos com tempo clínico e decisões criteriosas.</p><button class="btn" onclick="go('specialty')">Praticar</button></article></section><div class="build">Versão ${BUILD.version}</div></main>`}
function hub(){let p=state.player,pr=syncProgress();app.innerHTML=shell('LOBBY DO RESIDENTE',`<div class="layout">${sidebar('hub')}<section class="maincol"><div class="hero-card card" style="--cardbg:url('${bg(8)}')"><h1>Bem-vindo, ${p.short}</h1><p>Escolha sua próxima atividade e avance na jornada clínica.</p><div class="level medallion">${p.level}</div><div class="stats"><div>🏆<b>${p.xp}</b><small>XP total</small></div><div>🌐<b>#${p.rank}</b><small>Ranking local</small></div><div>👥<b>${p.patients}</b><small>Pacientes</small></div><div>🎯<b>${p.correct}%</b><small>Acerto</small></div></div></div><div class="two"><div class="card"><h3>Progresso da carreira</h3><p>${esc(careerLocalized(currentCareerStage()?.title)||p.title)} • Reputação ${p.reputation}</p><div class="xp big"><i style="width:${pr.pct}%"></i></div><p>${pr.spent} / ${pr.next} XP • Desbloqueadas: ${state.unlocks.specialties.join(', ')}</p><button class="btn primary" onclick="go('career')">Abrir carreira e residência</button><button class="btn" onclick="go('specialty')">Iniciar plantão</button><button class="btn outpatient-launch" onclick="openOutpatientCatalog()">📆 Centro de seguimento</button><button class="btn emergency-launch" onclick="openEmergencyCatalog()">⚡ Treino de emergência</button></div><div class="card"><h3>Últimos casos</h3>${state.completed.slice(-4).reverse().map(x=>`<p>✅ ${x.id} <b>${x.score}/100</b></p>`).join('')||'<p>Nenhum caso concluído ainda.</p>'}</div></div></section><aside class="rightcol"><div class="card"><h3>Missões e recompensas</h3>${missionBank.map(m=>`<div class='mission'><b>${m.type}</b><span>${m.title}</span><small>${missionProgress(m)} / ${m.goal}</small><button class='btn mini' onclick="claimMission('${m.id}')" ${canClaim(m)?'':'disabled'}>Coletar</button></div>`).join('')}</div><div class="card"><h3>Créditos</h3><h2>${p.credits}</h2><p>Conquiste créditos ao concluir casos, missões e atividades da carreira.</p></div></aside></div>`,8)}

