function outpatientMetricValue(program,key,value){const goal=program?.goals?.find(item=>item.metric===key);const unit=goal?.unit||'';const shown=Number.isInteger(Number(value))?Number(value):Number(value).toFixed(1);return `${shown}${unit?' '+unit:''}`;}
function outpatientCatalog(){const c=outpatientCopy();return `<div class="layout outpatient-layout">${sidebar('outpatient')}<section class="maincol outpatient-main"><div class="outpatient-hero card"><span>📆</span><div><small>${c.title}</small><h1>${c.choose}</h1><p>${c.subtitle}</p><b>${esc(c.disclaimer)}</b></div></div><div class="outpatient-catalog">${(outpatientRegistry?.programs||[]).map(item=>`<article class="card outpatient-program"><header><span>🩺</span><div><small>${item.totalVisits} ${c.followups} • ${item.visitIntervalWeeks} sem</small><h2>${esc(outpatientLocalized(item.title))}</h2></div></header><p>${esc(outpatientLocalized(item.summary))}</p><div class="outpatient-tags"><span>${esc(outpatientLocalized(item.condition))}</span><span>${item.age} ${tr('anos')}</span></div><button class="btn primary" onclick="startOutpatientProgram('${item.id}')">${esc(c.start)}</button></article>`).join('')}</div></section><aside class="rightcol"><div class="card"><h3>${c.progress}</h3><p>${state.outpatient.completed.length} ${c.completed.toLowerCase()}<br>${state.outpatient.xpClaimed.length} recompensas únicas</p><p class="muted">${esc(outpatientLocalized(outpatientRegistry?.policy?.disclaimer))}</p></div></aside></div>`;}
function outpatientGoalCards(program,session){const c=outpatientCopy();return `<div class="outpatient-goals">${(program.goals||[]).map(goal=>{const value=Number(session.metrics?.[goal.metric]);const met=goal.direction==='min'?value>=Number(goal.target):value<=Number(goal.target);return `<article class="${met?'met':'pending'}"><small>${met?c.goalMet:c.goalPending}</small><b>${esc(outpatientLocalized(goal.label))}</b><span>${outpatientMetricValue(program,goal.metric,value)} / ${goal.direction==='min'?'≥':'≤'} ${goal.target}${goal.unit?' '+goal.unit:''}</span></article>`;}).join('')}</div>`;}
function outpatientActionGroups(program,session){const c=outpatientCopy(),categories=['assessment','monitoring','communication','plan','barrier','safety','continuity','escalation','risk'];return categories.map(category=>{const items=(outpatientRegistry.actions||[]).filter(action=>action.category===category);if(!items.length)return '';return `<section class="card outpatient-action-group"><h3>${esc(({assessment:c.assessment,monitoring:c.monitoring,communication:c.communication,plan:c.planCategory,barrier:c.barrier,safety:c.safety,continuity:c.continuity,escalation:c.escalation,risk:c.riskCategory})[category]||category)}</h3>${items.map(action=>{const done=session.performedThisVisit.some(item=>item.actionId===action.id)&&!action.repeatable;const required=program.requiredActions.includes(action.id),helpful=program.helpfulActions.includes(action.id),harmful=action.harmful||program.harmfulActions.includes(action.id);const quality=required?c.required:helpful?c.helpful:harmful?c.harmful:'';return `<button class="outpatient-action ${done?'done':''} ${required?'required':''} ${harmful?'harmful':''}" onclick="doOutpatientAction('${action.id}')" ${done?'disabled':''}><span>${action.icon||'•'}</span><b>${esc(outpatientLocalized(action.label))}<small>${esc(outpatientLocalized(action.description))}</small></b><i>${done?'✓ '+c.performed:`${quality?quality+' • ':''}${c.perform}`}</i></button>`;}).join('')}</section>`;}).join('');}
function outpatientTimeline(session){const c=outpatientCopy();if(!session.timeline.length)return `<div class="card outpatient-empty"><p>${c.historyEmpty}</p></div>`;return `<div class="card outpatient-timeline">${session.timeline.slice().reverse().map(item=>{const action=outpatientAction(outpatientRegistry,item.actionId);const title=item.type==='visit-closed'?`${c.visit} ${item.visit} ${c.completed.toLowerCase()}`:item.type==='missed-visit'?c.missVisit:action?outpatientLocalized(action.label):item.type;return `<p><time>${c.week} ${item.week??0}</time><span><b>${esc(title)}</b><small>${item.penalty?`-${item.penalty} pontos • `:''}${esc(item.quality||'')}</small></span></p>`;}).join('')}</div>`;}
function outpatientDebrief(program,session){const c=outpatientCopy(),progress=outpatientProgress(session,program),rating=session.score>=85?c.excellent:session.score>=70?c.good:c.review;return `<section class="outpatient-result card"><small>${c.result}</small><h1>${session.score}/100</h1><h2>${esc(rating)}</h2><p><b>${c.outcome}:</b> ${esc(session.outcome)}</p><p><b>${c.goals}:</b> ${progress.goalsReached}/${progress.totalGoals}</p>${outpatientGoalCards(program,session)}<div class="outpatient-result-actions"><button class="btn primary" onclick="restartOutpatientProgram()">${c.repeat}</button><button class="btn" onclick="openOutpatientCatalog()">${c.catalog}</button></div></section>`;}
function outpatient(){const c=outpatientCopy(),program=currentOutpatientProgram(),session=state.outpatient?.session;if(!program||!session)return app.innerHTML=shell(c.title,outpatientCatalog(),8);const progress=outpatientProgress(session,program),activeTab=state.ui.outpatientTab||'summary';const body=session.status!=='active'?outpatientDebrief(program,session):`<div class="outpatient-command card"><div><small>${c.patient}</small><h1>${esc(outpatientLocalized(program.patient))}</h1><p>${program.age} ${tr('anos')} • ${esc(outpatientLocalized(program.sex))}</p></div><div class="outpatient-visit"><small>${c.visit}</small><b>${session.visit}/${program.totalVisits}</b><em>${c.week} ${session.week}</em></div><div class="outpatient-score"><small>${c.score}</small><b>${session.score}</b><em>${c.active}</em></div></div><div class="outpatient-status-grid"><div><small>${c.adherence}</small><b>${Math.round(session.adherence)}%</b></div><div><small>${c.engagement}</small><b>${Math.round(session.engagement)}%</b></div><div><small>${c.risk}</small><b>${Math.round(session.risk)}%</b></div><div><small>${c.symptoms}</small><b>${Math.round(session.symptom)}%</b></div></div><nav class="outpatient-tabs" role="tablist"><button class="${activeTab==='summary'?'active':''}" onclick="setOutpatientTab('summary')">👤 ${c.summary}</button><button class="${activeTab==='plan'?'active':''}" onclick="setOutpatientTab('plan')">🧭 ${c.plan}</button><button class="${activeTab==='timeline'?'active':''}" onclick="setOutpatientTab('timeline')">🕒 ${c.timeline}</button></nav><section class="outpatient-tab-body tab-${activeTab}">${activeTab==='summary'?`<div class="outpatient-summary-grid"><article class="card"><small>${c.condition}</small><h2>${esc(outpatientLocalized(program.title))}</h2><p>${esc(outpatientLocalized(program.summary))}</p><h3>${c.barriers}</h3><ul>${program.barriers.map(x=>`<li>${esc(outpatientLocalized(x))}</li>`).join('')}</ul><small>${c.source}: ${program.sourceIds.join(', ')}</small></article><article class="card"><small>${c.goals}</small>${outpatientGoalCards(program,session)}<div class="outpatient-progress"><span><b>${progress.requiredDone}/${progress.requiredTotal}</b> ações essenciais nesta consulta</span><i><u style="width:${Math.round(progress.requiredDone/Math.max(1,progress.requiredTotal)*100)}%"></u></i></div></article></div>`:activeTab==='plan'?outpatientActionGroups(program,session):outpatientTimeline(session)}</section><div class="outpatient-hud"><b>${c.visit} ${session.visit}/${program.totalVisits}</b><b>${c.goals} ${progress.goalsReached}/${progress.totalGoals}</b><button class="btn" onclick="missCurrentOutpatientVisit()">${c.missVisit}</button><button class="btn primary" onclick="closeCurrentOutpatientVisit()">${c.closeVisit}</button></div>`;app.innerHTML=shell(c.title,`<div class="outpatient-screen">${body}</div>`,8);}
window.openOutpatientCatalog=()=>{state.screen='outpatient';state.outpatient.programId=null;state.outpatient.session=null;state.ui.outpatientTab='summary';save({label:'outpatient-catalog'});render();};
window.startOutpatientProgram=id=>{const program=outpatientProgram(outpatientRegistry,id);if(!program)return toast('Linha de cuidado indisponível','warn');state.screen='outpatient';state.outpatient.programId=id;state.outpatient.session=createOutpatientSession(program);state.ui.outpatientTab='summary';save({label:'outpatient-start',forceBackup:true});render();};
window.restartOutpatientProgram=()=>{const program=currentOutpatientProgram();if(!program)return openOutpatientCatalog();state.outpatient.session=createOutpatientSession(program);state.ui.outpatientTab='summary';save({label:'outpatient-restart'});render();};
window.setOutpatientTab=tab=>{state.ui.outpatientTab=['summary','plan','timeline'].includes(tab)?tab:'summary';save({label:'outpatient-tab'});render();};
window.doOutpatientAction=id=>{const program=currentOutpatientProgram(),session=state.outpatient.session;const result=performOutpatientAction(session,outpatientRegistry,program,id);if(!result.ok)return toast(result.error,'warn');const action=outpatientAction(outpatientRegistry,id);toast(outpatientLocalized(action.label),result.record.quality==='harmful'?'warn':'ok');save({label:'outpatient-action'});render();};
function completeOutpatientProgram(){const program=currentOutpatientProgram(),session=state.outpatient.session;if(!program||!session)return;const key=program.id;if(!state.outpatient.xpClaimed.includes(key)){state.player.xp+=Math.round(70+session.score);state.player.credits+=session.score>=80?120:60;state.outpatient.xpClaimed.push(key);syncProgress();}if(!state.outpatient.completed.some(item=>item.id===key&&item.build===BUILD.version)){state.outpatient.completed.push({id:key,score:session.score,outcome:session.outcome,goals:outpatientProgress(session,program).goalsReached,build:BUILD.version,at:new Date().toISOString()});recordCareerActivity(state.career,{type:'outpatient',specialty:'outpatient',score:session.score,id:key});}save({label:'outpatient-complete',forceBackup:true});}
window.closeCurrentOutpatientVisit=()=>{const program=currentOutpatientProgram(),session=state.outpatient.session;const result=closeOutpatientVisit(session,program);if(!result.ok)return toast(result.error,'warn');if(result.completed)completeOutpatientProgram();else toast(`${outpatientCopy().visit} ${session.visit} • ${outpatientCopy().week} ${session.week}`,'ok');state.ui.outpatientTab='summary';save({label:'outpatient-visit-close',forceBackup:true});render();requestAnimationFrame(()=>window.scrollTo?.({top:0,left:0,behavior:'auto'}));};
window.missCurrentOutpatientVisit=()=>{const program=currentOutpatientProgram(),session=state.outpatient.session;const result=missOutpatientVisit(session,program);if(!result.ok)return toast(result.error,'warn');toast(outpatientCopy().missVisit,'warn');save({label:'outpatient-missed',forceBackup:true});render();};

