function stopEmergencyClock(){if(emergencyTimer){clearInterval(emergencyTimer);emergencyTimer=null;}}
function syncEmergencyClock(){stopEmergencyClock();const scenario=currentEmergencyScenario(),session=state.emergency?.session;if(state.screen!=='emergency'||!scenario||!session||session.status!=='active'||orientationBlocked||document.hidden)return;const seconds=Math.max(5,Number(emergencyRegistry?.tick?.realSecondsPerClinicalMinute||10));emergencyTimer=setInterval(()=>{if(state.screen!=='emergency'||document.hidden||orientationBlocked)return;const result=advanceEmergency(session,scenario,1,{reason:'continuous'});if(result.events?.length)toast(emergencyLocalized({ 'pt-BR':'Janela crítica em risco','en':'Critical window at risk','es':'Ventana crítica en riesgo'}),'warn');save({label:'emergency-tick'});render();},seconds*1000);emergencyTimer.unref?.();}

function applyRuntimePause(){
  const shouldPause=Boolean(orientationBlocked||document.hidden);
  if(shouldPause===runtimePaused)return;
  runtimePaused=shouldPause;
  if(shouldPause){
    if(state.simulation?.physiology){physiologyPauseBeforeLifecycle=Boolean(state.simulation.physiology.paused);state.simulation.physiology.paused=true;state.simulation.physiology.lastRealTickAt=Date.now();}
    stopPhysiologyClock();stopEmergencyClock();presentation.suspend();
    return;
  }
  if(state.simulation?.physiology){state.simulation.physiology.paused=Boolean(physiologyPauseBeforeLifecycle);state.simulation.physiology.lastRealTickAt=Date.now();}
  physiologyPauseBeforeLifecycle=null;
  syncPhysiologyClock();syncEmergencyClock();presentation.resume(state.screen);
}
function emergencyVitalGrid(session){const v=session.vitals||{};const rows=[['PA',`${Math.max(0,Math.round(v.systolic||0))}/${Math.max(0,Math.round(v.diastolic||0))}`],['FC',Math.max(0,Math.round(v.heartRate||0))],['FR',Math.max(0,Math.round(v.respiratoryRate||0))],['SpO₂',`${Math.max(0,Math.round(v.spo2||0))}%`],['Glicemia',`${Math.max(0,Math.round(v.glucose||0))}`]];return `<div class="emergency-vitals">${rows.map(([k,val])=>`<div><small>${k}</small><b>${val}</b></div>`).join('')}</div>`;}
function emergencyCatalog(){const c=emergencyCopy();return `<div class="layout emergency-layout">${sidebar('emergency')}<section class="maincol emergency-main"><div class="emergency-hero card"><span>⚡</span><div><small>${c.title}</small><h1>${c.choose}</h1><p>${c.subtitle}</p><b>${esc(c.disclaimer)}</b></div></div><div class="emergency-catalog">${(emergencyRegistry?.scenarios||[]).map(item=>`<article class="card emergency-scenario priority-${item.priority}"><header><span>${item.priority==='resuscitation'?'🫀':'🚨'}</span><div><small>${esc(c.priority)} • ${esc(c[item.priority]||item.priority)}</small><h2>${esc(emergencyLocalized(item.title))}</h2></div></header><p>${esc(emergencyLocalized(item.complaint))}</p><div><span>${item.age} ${tr('anos')}</span><span>${esc(emergencyLocalized(item.sex))}</span><span>${item.maxMinutes} min</span></div><button class="btn primary" onclick="startEmergencyScenario('${item.id}')">${esc(c.start)}</button></article>`).join('')}</div></section><aside class="rightcol"><div class="card"><h3>ABCDE</h3>${(emergencyRegistry?.stages||[]).map(stage=>`<p><b>${stage.id}</b> — ${esc(emergencyLocalized(stage.name))}</p>`).join('')}<p class="muted">${esc(emergencyLocalized(emergencyRegistry?.policy?.disclaimer))}</p></div></aside></div>`;}
function emergencyStageBar(session){return `<div class="abcde-bar">${(emergencyRegistry?.stages||[]).map(stage=>`<div class="${session.stageCompletion?.[stage.id]?'done':''}"><b>${stage.id}</b><small>${esc(emergencyLocalized(stage.name))}</small></div>`).join('')}</div>`;}
function emergencyActionGroups(scenario,session){const c=emergencyCopy();return (emergencyRegistry?.stages||[]).map(stage=>{const items=(emergencyRegistry.actions||[]).filter(action=>action.stage===stage.id);return `<section class="card emergency-action-group"><header><b>${stage.id}</b><div><small>${c.stage} ${stage.id}</small><h3>${esc(emergencyLocalized(stage.name))}</h3></div></header>${items.map(action=>{const done=session.performed.some(item=>item.actionId===action.id)&&!action.repeatable;const critical=scenario.criticalActions.includes(action.id);return `<button class="emergency-action ${done?'done':''} ${critical?'critical':''}" onclick="doEmergencyAction('${action.id}')" ${done?'disabled':''}><span>${action.icon||'•'}</span><b>${esc(emergencyLocalized(action.label))}<small>${esc(emergencyLocalized(action.description))}</small></b><i>${done?'✓ '+c.performed:c.doAction}</i></button>`;}).join('')}</section>`;}).join('');}
function emergencyTimeline(session){const c=emergencyCopy();if(!session.timeline.length)return `<div class="card emergency-empty"><p>${c.noTimeline}</p></div>`;return `<div class="card emergency-timeline">${session.timeline.slice().reverse().map(item=>{const action=emergencyAction(emergencyRegistry,item.actionId);return `<p><time>${Math.round(item.minute)} min</time><span><b>${esc(action?emergencyLocalized(action.label):item.message||item.type)}</b><small>${item.penalty?`-${item.penalty} pontos • `:''}${esc(item.quality||'')}</small></span></p>`;}).join('')}</div>`;}
function emergencyDebrief(scenario,session){const c=emergencyCopy(),progress=emergencyProgress(session,scenario),rating=session.score>=85?c.excellent:session.score>=70?c.good:c.review;return `<section class="emergency-result card"><small>${c.result}</small><h1>${session.score}/100</h1><h2>${esc(rating)}</h2><p><b>${c.outcome}:</b> ${esc(session.outcome)}</p><p><b>${c.time}:</b> ${Math.round(session.elapsedMinutes)} min</p><p><b>${c.missing}:</b> ${progress.missing.length?progress.missing.map(id=>esc(emergencyLocalized(emergencyAction(emergencyRegistry,id)?.label))).join(' • '):'—'}</p><div class="emergency-result-actions"><button class="btn primary" onclick="restartEmergencyScenario()">${c.repeat}</button><button class="btn" onclick="openEmergencyCatalog()">${c.catalog}</button></div></section>`;}
function emergency(){const c=emergencyCopy(),scenario=currentEmergencyScenario(),session=state.emergency?.session;if(!scenario||!session)return app.innerHTML=shell(c.title,emergencyCatalog(),8);const progress=emergencyProgress(session,scenario),activeTab=state.ui.emergencyTab||'summary';const body=session.status!=='active'?emergencyDebrief(scenario,session):`<div class="emergency-command card"><div><small>${c.patient}</small><h1>${esc(emergencyLocalized(scenario.patient))}</h1><p>${scenario.age} ${tr('anos')} • ${esc(emergencyLocalized(scenario.sex))}</p></div>${emergencyVitalGrid(session)}<div class="emergency-clock"><small>${c.time}</small><b>${Math.round(session.elapsedMinutes)} min</b><em>${emergencyStatusText(session.status)}</em></div></div>${emergencyStageBar(session)}<nav class="emergency-tabs" role="tablist"><button class="${activeTab==='summary'?'active':''}" onclick="setEmergencyTab('summary')">👤 ${c.summary}</button><button class="${activeTab==='actions'?'active':''}" onclick="setEmergencyTab('actions')">⚡ ${c.actions}</button><button class="${activeTab==='timeline'?'active':''}" onclick="setEmergencyTab('timeline')">🕒 ${c.timeline}</button></nav><section class="emergency-tab-body tab-${activeTab}">${activeTab==='summary'?`<div class="emergency-summary-grid"><article class="card"><small>${c.complaint}</small><h2>${esc(emergencyLocalized(scenario.title))}</h2><p>${esc(emergencyLocalized(scenario.complaint))}</p><div class="emergency-progress"><span><b>${progress.done}/${progress.total}</b> ${c.progress}</span><i><u style="width:${progress.pct}%"></u></i></div></article><article class="card warning"><small>${c.redFlags}</small><p>${esc(emergencyLocalized(scenario.redFlags))}</p><small>${c.sources}: ${scenario.sourceIds.join(', ')}</small></article></div>`:activeTab==='actions'?emergencyActionGroups(scenario,session):emergencyTimeline(session)}</section><div class="emergency-hud"><b>${c.score} ${session.score}</b><b>${c.progress} ${progress.done}/${progress.total}</b><button class="btn" onclick="openEmergencyCatalog()">${c.back}</button><button class="btn primary" onclick="finishEmergencyScenario()" ${session.status==='active'?'disabled':''}>${c.finish}</button></div>`;app.innerHTML=shell(c.title,`<div class="emergency-screen">${body}</div>`,8);}
window.openEmergencyCatalog=()=>{stopPhysiologyClock();stopEmergencyClock();state.screen='emergency';state.emergency.scenarioId=null;state.emergency.session=null;state.ui.emergencyTab='summary';save({label:'emergency-catalog'});render();};
window.startEmergencyScenario=id=>{const scenario=emergencyScenario(emergencyRegistry,id);if(!scenario)return toast('Cenário indisponível','warn');state.screen='emergency';state.emergency.scenarioId=id;state.emergency.session=createEmergencySession(scenario);state.ui.emergencyTab='summary';save({label:'emergency-start',forceBackup:true});render();};
window.restartEmergencyScenario=()=>{const scenario=currentEmergencyScenario();if(!scenario)return openEmergencyCatalog();state.emergency.session=createEmergencySession(scenario);state.ui.emergencyTab='summary';save({label:'emergency-restart'});render();};
window.setEmergencyTab=tab=>{state.ui.emergencyTab=['summary','actions','timeline'].includes(tab)?tab:'summary';save({label:'emergency-tab'});render();};
window.doEmergencyAction=id=>{const scenario=currentEmergencyScenario(),session=state.emergency.session;const result=performEmergencyAction(session,emergencyRegistry,scenario,id);if(!result.ok)return toast(result.error,'warn');const action=emergencyAction(emergencyRegistry,id);toast(emergencyLocalized(action.label),result.record.quality==='harmful'?'warn':'ok');if(session.status!=='active')completeEmergencyScenario();else save({label:'emergency-action'});render();};
function completeEmergencyScenario(){const scenario=currentEmergencyScenario(),session=state.emergency.session;if(!scenario||!session)return;const key=scenario.id;const already=state.emergency.xpClaimed.includes(key);if(!already){const xp=Math.round(80+session.score*1.2);state.player.xp+=xp;state.player.credits+=session.score>=80?140:70;state.emergency.xpClaimed.push(key);syncProgress();}if(!state.emergency.completed.some(item=>item.id===key&&item.build===BUILD.version)){state.emergency.completed.push({id:key,score:session.score,outcome:session.outcome,build:BUILD.version,at:new Date().toISOString()});recordCareerActivity(state.career,{type:'emergency',specialty:'emergency',score:session.score,id:key});}save({label:'emergency-complete',forceBackup:true});}
window.finishEmergencyScenario=()=>{const session=state.emergency.session;if(!session)return;if(session.status==='active')return toast('Conclua as ações críticas ou aguarde o desfecho','warn');completeEmergencyScenario();render();};
