function settings(){
  const store=stateStore.inspect();
  const backups=store.backups.filter(item=>item.ok).length;
  app.innerHTML=shell('CONFIGURAÇÕES',`<div class="layout">${sidebar('settings')}<section class="settings-grid"><div class="card general-settings"><h2>Geral</h2><p>Escolha o idioma da interface e dos casos clínicos. A alteração é aplicada imediatamente.</p><label for="locale-select">Idioma</label><select id="locale-select" class="input" onchange="setAppLocale(this.value)">${SUPPORTED_LOCALES.map(item=>`<option value="${item.id}" ${state.locale===item.id?'selected':''}>${item.label}</option>`).join('')}</select><div class="keyboard-help"><h3>Atalhos de teclado</h3><p><kbd>Alt</kbd> + <kbd>1</kbd> Lobby • <kbd>2</kbd> Carreira • <kbd>3</kbd> Aprendizagem • <kbd>4</kbd> Plantão • <kbd>5</kbd> Seguimento • <kbd>6</kbd> Configurações • <kbd>8</kbd> Resultados</p><p><kbd>Esc</kbd> fecha janelas e menus. Setas navegam entre abas.</p></div></div>${accessibilitySettingsCard()}${presentationSettingsCard()}<div class="card"><h2>Aplicativo</h2><p>Versão ${BUILD.version}<br>Conexão: <b>${pwaStatus.online?'online':'offline'}</b><br>Modo: <b>${pwaStatus.installed?'aplicativo instalado':'navegador'}</b></p>${pwaStatus.installAvailable?'<button class="btn primary" onclick="installGame()">Instalar aplicativo</button>':''}${swStatus.updateReady?'<button class="btn primary" onclick="applyGameUpdate()">Aplicar atualização</button>':''}</div><div class="card"><h2>Meu progresso</h2><p>O progresso é salvo automaticamente neste dispositivo. Backups disponíveis: <b>${backups}</b>.</p><button class="btn primary" onclick="openRecoveryCenter()">Gerenciar progresso</button><button class="btn" onclick="createManualBackup()">Criar backup</button><button class="btn" onclick="safeExportSave()">Exportar progresso</button></div></section></div>`,10);
}

function recovery(){
  const store=stateStore.inspect();
  const validBackups=store.backups.filter(item=>item.ok);
  app.innerHTML=shell('MEU PROGRESSO',`<div class="layout">${sidebar('recovery')}<section class="maincol"><div class="card recovery-hero"><h1>Gerenciar progresso</h1><p>Crie cópias de segurança, restaure uma versão anterior ou corrija apenas a sessão atual sem apagar sua carreira.</p><div class="recovery-actions"><button class="btn primary" onclick="repairTransientState()">Retomar pelo lobby</button><button class="btn" onclick="createManualBackup()">Criar backup</button><button class="btn" onclick="safeExportSave()">Exportar progresso</button></div></div><div class="card"><h2>Backups disponíveis</h2>${validBackups.length?store.backups.map((item,index)=>item.ok?`<article class="backup-row"><div><b>${esc(item.playerName)}</b><small>${item.updatedAt?fmtDate(item.updatedAt):'Data indisponível'} • nível ${item.level} • ${item.xp} XP</small></div><button class="btn mini" onclick="restoreBackupAt(${index})">Restaurar</button></article>`:'').join(''):'<p>Nenhum backup foi criado ainda.</p>'}</div><div class="card"><h2>Recomeçar</h2><p>Use esta opção somente se quiser iniciar um novo perfil neste dispositivo.</p><button class="btn danger" onclick="resetLocalSave()">Apagar perfil atual</button></div></section><aside class="rightcol"><div class="card"><h3>Proteção automática</h3><p>O jogo confirma o progresso antes de substituir o salvamento anterior e mantém cópias recentes para recuperação.</p></div></aside></div>`,8)
}

function focusClinicalPanel(){
  try{
    if(!matchMedia('(max-width: 980px)').matches)return;
    const board=document.querySelector('.mobile-clinical-strip');
    if(board){board.classList.add('focus-pulse');setTimeout(()=>board.classList.remove('focus-pulse'),900)}
  }catch(e){}
}
window.pickAvatar=i=>{sound('tap');state.player.avatar=i;save();render()};window.startGame=()=>{state.player.name=document.querySelector('#name').value||'Dr. Rafael Santos';state.player.short=state.player.name.split(' ').slice(0,2).join(' ');go('menu')};
async function requestGameFullscreen(){
  document.body.classList.add('mobile-fullscreen-active');
  const result=await mobileExperience.toggleFullscreen();
  if(result.ok){toast(document.fullscreenElement?'Tela cheia ativada':'Tela cheia encerrada','ok');return;}
  if(pwaStatus.installed){toast('O aplicativo já está em modo imersivo','ok');return;}
  toast('Use “Adicionar à tela inicial” para o modo imersivo completo','warn');
}
async function installGame(){
  const result=await mobileExperience.install();
  state.pwa.lastInstallResult=result.outcome||result.reason||null;
  if(result.ok){toast('Instalação confirmada','ok');}
  else if(result.reason==='unavailable'){toast('Instalação disponível pelo menu do navegador','warn');}
  else toast('Instalação não concluída','warn');
  save({label:'pwa-install'});render();
}

