window.exportBetaFeedback=()=>{const alias=String(document.querySelector('#beta-alias')?.value||'').trim().slice(0,60),title=String(document.querySelector('#beta-title')?.value||'').trim().slice(0,120),description=String(document.querySelector('#beta-description')?.value||'').trim().slice(0,2400),steps=String(document.querySelector('#beta-steps')?.value||'').trim().slice(0,1800),category=String(document.querySelector('#beta-category')?.value||'other'),severity=String(document.querySelector('#beta-severity')?.value||'minor');if(!title||!description)return toast(betaCopy().required,'warn');state.beta.testerAlias=alias;const report={kind:'medical-simulator-closed-beta-feedback',schemaVersion:1,build:BUILD.label,channel:BETA_PROGRAM.channel,createdAt:new Date().toISOString(),testerAlias:alias||null,issue:{category,severity,title,description,steps:steps||null,screen:state.screen,locale:state.locale},audit:state.beta.lastAudit||null,environment:{userAgent:navigator.userAgent||'unknown',online:navigator.onLine,viewport:`${innerWidth}x${innerHeight}`,displayMode:pwaStatus.displayMode},diagnostics:state.beta.includeDiagnostics?diagnostics.export():null,saveSummary:state.beta.includeSaveSummary?betaSaveSummary():null};state.beta.reports.push({createdAt:report.createdAt,title,severity,category});state.beta.reports=state.beta.reports.slice(-10);save({label:'beta-feedback',forceBackup:true});betaObservability.record('feedback-export',{category,severity,screen:state.screen});downloadBetaJson(report,`medical-simulator-beta-feedback-${BUILD.stamp}.json`);toast('Relatório beta exportado','ok');render();};
