window.reassessPatient=()=>{const {session,profile}=currentPhysiology();const cost=Number(physiologyRegistry?.actionTimeCost?.reassessment??2);const result=reassessPhysiology(session,profile,cost);syncPhysiologyState();handlePhysiologyEvents(result.events);processReadyDiagnostics({notify:true});const v=latestVitals();ensureClinicalState();state.prontuario.notes.push({time:minToClock(),label:'Reavaliação fisiológica',result:`PA ${v.pa}, FC ${v.fc}, FR ${v.fr}, SpO₂ ${v.spo2}%, sintomas ${v.symptom}/100.`,detail:`Estado: ${v.status}. Reserva fisiológica simulada: ${v.reserve}%.`,caseId:activeCase().id});state.timeline.push({t:minToClock(),text:'Sinais vitais e sintomas reavaliados'});state.encounter={kind:'Reavaliação',title:'Nova avaliação registrada',text:`Estado atual: ${v.status}. Sintomas ${v.symptom}/100 e reserva ${v.reserve}%.`,detail:'Modelo educacional determinístico; não representa previsão clínica real.',time:minToClock()};save({label:'physiology-reassessment'});toast('Reavaliação registrada','ok');render();};
