window.openAcademyModule=id=>{const item=academyModuleById(id);if(!item||!academyModuleUnlocked(item))return toast(au('prerequisite'),'warn');state.ui.academyView='module';state.ui.academyModuleId=id;state.ui.academyQuizFeedback=null;const c=academyLocalized(item);const firstIncomplete=(c.lessons||[]).findIndex(lesson=>!state.academy.completedLessons?.[academyLessonKey(item.id,lesson.id)]);state.ui.academyLessonIndex=firstIncomplete>=0?firstIncomplete:0;state.academy.startedAt=state.academy.startedAt||new Date().toISOString();state.academy.lastActivity=new Date().toISOString();save({label:'academy-open'});render();};
