window.completeAcademyLesson=(moduleId,index)=>{const item=academyModuleById(moduleId),c=academyLocalized(item);if(!item||!c)return;const lesson=c.lessons[Number(index)];if(!lesson)return;state.academy.completedLessons[academyLessonKey(item.id,lesson.id)]=true;state.academy.lastActivity=new Date().toISOString();const next=Number(index)+1;if(next<c.lessons.length){state.ui.academyLessonIndex=next;state.ui.academyView='module';toast(au('lessonDone'),'ok');}else{state.ui.academyView='quiz';state.ui.academyQuizFeedback=null;toast(au('lessonDone'),'ok');}save({label:'academy-lesson-complete'});render();};
window.openAcademyQuiz=()=>{const item=academyModuleById(),c=academyLocalized(item);if(!item||academyLessonsDone(item)!==(c?.lessons?.length||0))return toast(au('completeLessonsFirst'),'warn');state.ui.academyView='quiz';state.ui.academyQuizFeedback=null;save({label:'academy-quiz'});render();};
window.clearAcademyQuizFeedback=()=>{state.ui.academyQuizFeedback=null;render();};
window.answerAcademyCheckpoint=answerIndex=>{const item=academyModuleById(),c=academyLocalized(item);if(!item||!c||academyLessonsDone(item)!==c.lessons.length)return toast(au('completeLessonsFirst'),'warn');const answer=Number(answerIndex),correct=answer===c.checkpoint.correctIndex;state.academy.attempts[item.id]=(state.academy.attempts[item.id]||0)+1;let awarded=false;if(correct){state.academy.passedModules[item.id]=true;if(!state.academy.xpClaimed.includes(item.id)){state.academy.xpClaimed.push(item.id);state.player.xp+=academyContent.xpPerModule||45;awarded=true;}state.player.learnedModules=Object.keys(state.academy.passedModules).filter(id=>state.academy.passedModules[id]).length;syncProgress();toast(awarded?`${au('moduleComplete')} +${academyContent.xpPerModule||45} XP`:`${au('moduleComplete')} • ${au('earnedOnce')}`,'ok');}else toast(au('incorrect'),'warn');state.ui.academyQuizFeedback={correct,explanation:c.checkpoint.explanation,awarded};state.academy.lastActivity=new Date().toISOString();save({label:'academy-checkpoint',forceBackup:correct});render();};
window.startAcademyPretest=()=>{state.academy.pretest={current:0,answers:[],correct:0,completed:false,score:null};state.ui.academyView='pretest';save({label:'academy-pretest-start'});render();};
window.answerAcademyPretest=answerIndex=>{const pre=state.academy.pretest,content=academyContent?.pretest?.[state.locale]||academyContent?.pretest?.['pt-BR'],question=content?.questions?.[pre.current||0];if(!question)return;const correct=Number(answerIndex)===question.correctIndex;pre.answers.push({answerIndex:Number(answerIndex),correct});if(correct)pre.correct+=1;pre.current+=1;if(pre.current>=content.questions.length){pre.completed=true;pre.score=Math.round(pre.correct/content.questions.length*100);pre.current=content.questions.length;}save({label:'academy-pretest-answer'});render();};
