window.answerAcademyGuided=answerIndex=>{const item=academyModuleById('guided-reasoning'),c=academyLocalized(item),guided=c?.guidedCase,g=state.academy.guided,step=guided?.steps?.[g.current||0];if(!step)return;const answer=Number(answerIndex),correct=answer===step.correctIndex;g.answers.push({answerIndex:answer,correct});if(correct)g.correct+=1;g.current+=1;if(g.current>=guided.steps.length){g.completed=true;g.score=Math.round(g.correct/guided.steps.length*100);let awarded=false;if(!state.academy.xpClaimed.includes('guided-case')){state.academy.xpClaimed.push('guided-case');state.player.xp+=academyContent.xpGuidedCase||90;syncProgress();awarded=true;}toast(awarded?`${au('guidedComplete')} +${academyContent.xpGuidedCase||90} XP`:`${au('guidedComplete')} • ${au('earnedOnce')}`,'ok');}save({label:'academy-guided-answer',forceBackup:g.completed});render();};
