window.answerCareerQuestion=index=>{const result=answerCareerExam(state.career,careerRegistry,index);if(!result.ok)return toast('Exam error','warn');if(result.completed){if(result.passed){state.career.examRewardsClaimed=state.career.examRewardsClaimed||[];const firstReward=!state.career.examRewardsClaimed.includes(result.exam.id);if(firstReward){state.career.examRewardsClaimed.push(result.exam.id);state.player.xp+=150;state.player.credits+=100;syncProgress();}toast(`${careerCopy().passed} • ${result.score}/100${firstReward?' • +150 XP':` • ${careerCopy().rewardedOnce||'recompensa já recebida'}`}`,'level');}else toast(`${careerCopy().failed} • ${result.score}/100`,'warn');save({label:'career-exam-complete',forceBackup:true});}else save({label:'career-exam-answer'});render();};
